class Shell extends StatefulWidget { const Shell({super.key}); @override State<Shell> createState() => _ShellState(); }
class _ShellState extends State<Shell> {
  final old.Store store = old.Store(); int tab = 0; bool loading = true;
  @override void initState() { super.initState(); store.load().then((_) { if (mounted) setState(() => loading = false); }); }
  void refresh() { if (mounted) setState(() {}); }
  Future<void> register() async { await Navigator.push(context, MaterialPageRoute(builder: (_) => old.ShopRegistrationPage(store: store))); refresh(); }
  Future<bool> gate(BuildContext context) async {
    if (store.registered) return true;
    final yes = await showDialog<bool>(context: context, builder: (c) => AlertDialog(title: const Text('Register your shop first'), content: const Text('Register your shop before making an entry. You can keep browsing by choosing Later.'), actions: [TextButton(onPressed: () => Navigator.pop(c, false), child: const Text('Later')), FilledButton.icon(onPressed: () => Navigator.pop(c, true), icon: const Icon(Icons.storefront_rounded), label: const Text('Register Shop'))]));
    if (yes == true && context.mounted) await register();
    return store.registered;
  }
  @override Widget build(BuildContext c) {
    if (loading) return const Scaffold(body: Center(child: CircularProgressIndicator(color: rp)));
    final pages = [Home(store: store, register: register, gate: gate), Inventory(store: store, gate: gate, refresh: refresh), Customers(store: store, gate: gate, refresh: refresh), Rentals(store: store, gate: gate, refresh: refresh), Settings(store: store, register: register)];
    return PopScope(canPop: tab == 0, onPopInvokedWithResult: (didPop, result) { if (!didPop && tab != 0) setState(() => tab = 0); }, child: Scaffold(body: pages[tab], bottomNavigationBar: NavigationBar(height: 76, backgroundColor: Colors.white, indicatorColor: rs, selectedIndex: tab, onDestinationSelected: (v) => setState(() => tab = v), destinations: const [NavigationDestination(icon: Icon(Icons.grid_view_rounded), label: 'Home'), NavigationDestination(icon: Icon(Icons.inventory_2_outlined), label: 'Inventory'), NavigationDestination(icon: Icon(Icons.people_outline_rounded), label: 'Customers'), NavigationDestination(icon: Icon(Icons.assignment_outlined), label: 'Rentals'), NavigationDestination(icon: Icon(Icons.settings_outlined), label: 'Settings')]));
  }
}

