      Row(children: [const Text('Issued quantity', style: TextStyle(fontWeight: FontWeight.w800)), const Spacer(), IconButton(onPressed: qty > 1 ? () => set(() => qty--) : null, icon: const Icon(Icons.remove_circle_outline)), Text('$qty', style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w900)), IconButton(onPressed: qty < available ? () => set(() => qty++) : null, icon: const Icon(Icons.add_circle_outline, color: rp))]), Align(alignment: Alignment.centerLeft, child: Text('Available: $available', style: const TextStyle(color: Colors.black54, fontSize: 12))), const SizedBox(height: 10), Container(padding: const EdgeInsets.all(14), decoration: BoxDecoration(color: rs, borderRadius: BorderRadius.circular(16)), child: Row(children: [const Text('Total rent', style: TextStyle(fontWeight: FontWeight.w800)), const Spacer(), Text(old.money(old.asDouble(item['rent']) * qty), style: const TextStyle(fontSize: 20, fontWeight: FontWeight.w900, color: rp))])),
